def secant_limit():
 p=(185,170);qs=[(375,170),(365,127.573593),(345,100.717968)]
 paths=[path(ellipse(280,170,95,95)),path([(185,45),(185,285)]),path([(125,170),p])]+[path([p,q]) for q in qs]
 return geometry('Figure 8.8','Figure 8.8 — secants through P approach the tangent; the normal is perpendicular',[*paths],[(167,40,'T'),(160,302,'Tangent'),(105,157,'R'),(115,195,'Normal'),(168,172,'P'),(378,177,'Q'),(369,125,'Q'),(347,96,'Q'),(273,185,'Secant')],points=[{'x':p[0],'y':p[1]}],size=(440,330))
def chord_geometry():
 m,c,r=.6,40,100
 roots=[(-m*c+sgn*sqrt(r*r*(1+m*m)-c*c))/(1+m*m) for sgn in [1,-1]]
 def pt(x,y):return(250+x,190-y)
 P,Q=[pt(x,m*x+c) for x in roots];M=pt(-m*c/(1+m*m),c/(1+m*m));O=pt(0,0)
 paths=[path(ellipse(*O,r,r)),path([pt(-150,0),pt(150,0)]),path([pt(0,-125),pt(0,135)]),path([pt(-140,m*(-140)+c),pt(145,m*145+c)]),path([O,P]),path([O,M])]
 return geometry('Figure 8.9','Figure 8.9 — secant PQ, perpendicular OM and half-chord MP',paths,[(406,196,'x'),(246,48,'y'),(231,212,'O'),(P[0]+4,P[1]-9,'P'),(Q[0]-18,Q[1]-7,'Q'),(M[0]-17,M[1]-13,'M'),(278,156,'a'),(117,244,'B'),(380,69,'A'),(126,287,'OM < OP')],points=[{'x':M[0],'y':M[1]}],size=(440,320))
PAGES=[page('115_page_2.jpg',222,[heading('8.3 Tangents and Normal'),paragraph('If a secant PQ of a circle is moved upward about one of its points of intersection P, then the second point of intersection Q is moving gradually along the curve that tends to coincide with P. The limiting position PT of PQ is then called the tangent to the circle at the point P.'),secant_limit(),paragraph('The point of the circle at which a tangent meets the circle is called point of contact (Say P) of the tangent. The normal at a contact point P to a circle (or conic) is the straight line PR perpendicular to the tangent PT to the circle (or conic) at that point P.'),
 heading('8.3.1 The condition when a line intersect the circle'),paragraph('The circle and the line are'),eq(r'x^2+y^2=a^2','i'),eq(r'y=mx+c','ii'),paragraph('which develops a system of two nonlinear equations:'),eq(r'x^2+y^2=a^2,\quad y=mx+c','iii'),paragraph('The solution set {(x,y)} of the nonlinear system of equations (iii) exists only, when the curves of the system (iii) are intersecting. That set of points of intersection {(x,y)} is the solution set, can be found by solving the nonlinear system (iii) simultaneously.'),paragraph('The line (ii) is used in a circle (i) to obtain the quadratic equation in x:'),eq(r'x^2+(mx+c)^2=a^2'),eq(r'x^2(1+m^2)+2mcx+(c^2-a^2)=0','iv'),paragraph('The equation (iv) being a quadratic equation in x, gives a set of two values x₁ and x₂ of x which will be used in a line (ii) to obtain a set of two y values y₁ and y₂. The solution set {(x₁,y₁),(x₂,y₂)} of the system (iii) is of course a set of points of intersection of the line and circle.'),paragraph('The points of intersection are real, coincident or imaginary, according as the roots of the quadratic equation (iv) are real, coincident or imaginary or according as the discriminate of the quadratic equation (iv):'),eq(r'\mathrm{disc}=4m^2c^2-4[(1+m^2)(c^2-a^2)]>0,\quad\mathrm{real\ and\ distant}'),eq(r'\mathrm{disc}=4m^2c^2-4[(1+m^2)(c^2-a^2)]=0,\quad\mathrm{coincident}'),eq(r'\mathrm{disc}=4m^2c^2-4[(1+m^2)(c^2-a^2)]<0,\quad\mathrm{imaginary}'),note('For a real nondegenerate circle take a > 0. A positive discriminant means two distinct real intersections; zero means one repeated contact point; negative means no real intersection, not actual imaginary points in the real plane. The slope form excludes vertical lines, which can instead be tested by perpendicular center-to-line distance.'),
 heading('Example 7'),paragraph('Find the points of intersection of the line 3x−4y+20 = 0 and the circle x²+y² = 25.'),heading('Solution'),paragraph('The equations of the line and circle are:'),eq(r'3x-4y+20=0\ \Rightarrow\ y=\frac34x+5','i'),eq(r'x^2+y^2=25','ii'),paragraph('The line (i) is used in a circle (ii) to obtain the x-coordinates of the points of intersection:'),eq(r'x^2+\left(\frac34x+5\right)^2=25'),eq(r'x^2+\frac9{16}x^2+25+\frac{30}4x=25')]),
 page('116_page_1.jpg',223,[eq(r'x^2+\frac9{16}x^2+\frac{30}4x=0\ \Rightarrow\ 25x^2+120x=0\ \Rightarrow\ x=0,-\frac{24}5'),paragraph('The x-coordinates x = 0, −24/5 are used in the line (i) to obtain the y-coordinates:'),eq(r'x=0\ \mathrm{gives}\ y=5'),eq(r'x=-\frac{24}5\ \mathrm{gives}\ y=\frac34\left(-\frac{24}5\right)+5=\frac{-72+100}{20}=\frac{28}{20}=\frac75'),paragraph('Thus, the points of intersection (0,5) and (−24/5,7/5) are real and distant.'),heading('8.3.2 Condition when a line touches the circle x²+y² = a²'),paragraph('To determine the position of a line with respect to the circle, we need to find its distance from centre of a circle and compare with radius then: i. If distance is less than the radius, the line will intersect at two points. ii. If distance is equal to the radius, then the line will touch the circle. iii. If distance is greater than the radius, the line will completely outside the circle.'),chord_geometry(),paragraph('Let AB be the straight line y = mx+c that intersects the circle x²+y² = a² at points P and Q respectively. Join OP and put it by OP = a, which is the radius of a given circle. Draw OM perpendicular on PQ. If OM is perpendicular to PQ, then the perpendicular distance OM from O(0,0) on a secant line mx−y+c = 0 (line PQ) is:'),eq(r'OM=\frac{|m(0)-(0)+c|}{\sqrt{m^2+1}}=\frac c{\sqrt{1+m^2}}'),paragraph('From the right-angled triangle OMP, it is known that:'),eq(r'|OP|^2=|OM|^2+|MP|^2'),eq(r'|MP|^2=|OP|^2-|OM|^2=a^2-\frac{c^2}{1+m^2}=\frac{a^2(1+m^2)-c^2}{1+m^2}'),eq(r'|MP|=\sqrt{\frac{a^2(1+m^2)-c^2}{1+m^2}}'),paragraph('The secant line PQ is 2 times of OM, and the length of the intercept PQ is therefore:'),eq(r'|PQ|=2|OM|=2\sqrt{\frac{a^2(1+m^2)-c^2}{1+m^2}}','ii'),heading('Condition of Tangency'),paragraph('The line y = mx+c touches the circle x²+y² = a², if the length of the intercept PQ is zero:'),eq(r'2\sqrt{\frac{a^2(1+m^2)-c^2}{1+m^2}}=0'),note('OM is the perpendicular distance from the center to the chord, not its half-length. The diameter-perpendicular chord theorem gives PQ = 2MP, and the displayed radical calculates MP. The source’s repeated 2OM labels are retained with this correction. The final equality for distance also needs |c|, rather than c, unless c ≥ 0; its square c² is nevertheless correct. Tangency is equivalent to c² = a²(1+m²), or c = ±a√(1+m²) for a > 0.')])]
